-- TARGET SYSTEM: WEBSITE  (Supabase project jrykbzdzcplhrhauvlvk)
-- NOT the intranet project (ecjsdvylsuchsjxnhgxf). Check the project ref in the
-- dashboard URL before running — the selector remembers whichever was open last.
--
-- GENERATED by scripts/gen-amenity-migration.mjs from lib/amenities.ts.
-- Do not edit this file by hand: edit the array there and regenerate, or the
-- code fallback and the live list drift apart again.
--
-- Make the amenity list canonical: 31 entries (15 in the unit,
-- 16 in the building), no duplicates, Title Case English.
--
-- WHAT WAS WRONG
--   · เครื่องทำน้ำอุ่น was saved twice (ids 1783608202476, 1791993263976).
--     The form keys selection off name_th, so both buttons toggled as one.
--   · รับสัตว์เลี้ยง and เลี้ยงสัตว์ได้ were the same amenity under two stored
--     values, so a tenant filtering on one missed every listing tagged with the
--     other. รับสัตว์เลี้ยง survives.
--   · name_en mixed Title Case with lower case ("pet allow", "electric stove").
--     Invisible in Thai; visible on the English form shipped 16 Oct 2026.
--   · DEFAULT_AMENITIES in code shared only 3 of 28 names with the live list,
--     so the fallback could write names the picker would never offer again.
--
-- RUN ORDER: 1 to inspect, 2 to back up, 3 to write the list, 4 to migrate the
-- listings, 5 to verify. Sections 3 and 4 are independent — 3 fixes the picker,
-- 4 fixes what is already stored.

-- ─────────────────────────────────────────────────────────────────────────────
-- 1 · INSPECT
-- ─────────────────────────────────────────────────────────────────────────────

-- 1a. Confirm amenities is text[] (udt_name _text). If it is jsonb, stop —
--     section 4 uses unnest and would error.
select column_name, data_type, udt_name
from information_schema.columns
where table_name = 'properties' and column_name = 'amenities';

-- 1b. The current stored list, and whether the listings carrying it are live.
select a.name,
       count(*) as listings,
       count(*) filter (where p.listing_status = 'active') as active
from properties p, unnest(p.amenities) as a(name)
group by a.name
order by listings desc, a.name;

-- 1c. Rows section 4 will change: anything holding a legacy name, or a duplicate.
select count(*) as rows_to_change
from properties p
where exists (
  select 1 from unnest(p.amenities) as a(name)
  where a.name in ('แอร์', 'เแอร์', 'เลี้ยงสัตว์ได้', 'เฟอร์นิเจอร์ครบ', 'อินเทอร์เน็ต', 'เตาไฟฟ้า', 'ฟิตเนส', 'รักษาความปลอดภัย 24 ชม.', 'กล้องวงจรปิด', 'ลิฟต์')
)
or array_length(p.amenities, 1) <> (select count(distinct x) from unnest(p.amenities) as x);


-- ─────────────────────────────────────────────────────────────────────────────
-- 2 · BACK UP
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists properties_amenities_backup_20261016 as
select id, slug, amenities, now() as backed_up_at
from properties;

select count(*) as backed_up from properties_amenities_backup_20261016;

-- And the settings row, which section 3 overwrites.
create table if not exists site_settings_amenities_backup_20261016 as
select * from site_settings where key = 'amenities';

select count(*) as settings_rows_backed_up from site_settings_amenities_backup_20261016;


