-- ─────────────────────────────────────────────────────────────────────────────
-- 4 · MIGRATE WHAT IS ALREADY STORED
-- ─────────────────────────────────────────────────────────────────────────────
--
-- Renames the legacy values and removes duplicates in one pass. Order within
-- each array is not preserved — the public page groups by section and does not
-- depend on it.

with renames(from_name, to_name) as (
  values
    ('แอร์', 'เครื่องปรับอากาศ'),
    ('เแอร์', 'เครื่องปรับอากาศ'),
    ('เลี้ยงสัตว์ได้', 'รับสัตว์เลี้ยง'),
    ('เฟอร์นิเจอร์ครบ', 'เฟอร์นิเจอร์พร้อมอยู่'),
    ('อินเทอร์เน็ต', 'WiFi'),
    ('เตาไฟฟ้า', 'เตาแม่เหล็กไฟฟ้า'),
    ('ฟิตเนส', 'ห้องออกกำลังกาย (GYM)'),
    ('รักษาความปลอดภัย 24 ชม.', 'รปภ 24 ชม'),
    ('กล้องวงจรปิด', 'กล้องวงจรปิด (CCTV)'),
    ('ลิฟต์', 'ลิฟท์')
),
fixed as (
  select p.id,
         (
           select array_agg(distinct coalesce(r.to_name, a.name))
           from unnest(p.amenities) as a(name)
           left join renames r on r.from_name = a.name
         ) as amenities
  from properties p
  where p.amenities is not null
    and array_length(p.amenities, 1) > 0
)
update properties p
set amenities = f.amenities
from fixed f
where p.id = f.id
  and p.amenities is distinct from f.amenities;


