-- ─────────────────────────────────────────────────────────────────────────────

-- 5a. No legacy name survives. Expect zero rows.
select a.name, count(*) as listings
from properties p, unnest(p.amenities) as a(name)
where a.name in ('แอร์', 'เแอร์', 'เลี้ยงสัตว์ได้', 'เฟอร์นิเจอร์ครบ', 'อินเทอร์เน็ต', 'เตาไฟฟ้า', 'ฟิตเนส', 'รักษาความปลอดภัย 24 ชม.', 'กล้องวงจรปิด', 'ลิฟต์')
group by a.name;

-- 5b. No listing holds the same amenity twice. Expect zero rows.
select p.slug, a.name, count(*) as times
from properties p, unnest(p.amenities) as a(name)
group by p.slug, a.name
having count(*) > 1;

-- 5c. Anything stored that the canonical list does not offer. These still
--     display (groupSelected keeps unknowns) but match no filter — worth a
--     look rather than an automatic change.
select a.name, count(*) as listings
from properties p, unnest(p.amenities) as a(name)
where a.name not in ('เครื่องปรับอากาศ',
                     'เฟอร์นิเจอร์พร้อมอยู่',
                     'เฟอร์นิเจอร์บางส่วน',
                     'WiFi',
                     'เครื่องซักผ้า',
                     'เครื่องทำน้ำอุ่น',
                     'เตาแม่เหล็กไฟฟ้า',
                     'ไมโครเวฟ',
                     'ตู้เย็น',
                     'โทรทัศน์',
                     'โซฟา',
                     'โต๊ะกินข้าว',
                     'ห้องครัว',
                     'ระเบียง',
                     'รับสัตว์เลี้ยง',
                     'ที่จอดรถ',
                     'สระว่ายน้ำ',
                     'ห้องออกกำลังกาย (GYM)',
                     'รปภ 24 ชม',
                     'กล้องวงจรปิด (CCTV)',
                     'ลิฟท์',
                     'ระบบ Keycard',
                     'ใกล้ห้างสรรพสินค้า',
                     'ห้องซักรีด',
                     'ร้านซักรีด',
                     'ร้านสะดวกซื้อ',
                     'ร้านอาหาร',
                     'สวนสาธารณะ',
                     'ห้องเกม',
                     'สนามบาสเกตบอล',
                     'ตู้หยอดเหรียญ')
group by a.name
order by listings desc;

-- 5d. What changed, by status. No listing should have lost an amenity it had,
--     except where two names collapsed into one.
select p.listing_status,
       count(*) as changed,
       sum(coalesce(array_length(b.amenities, 1), 0)) as before_total,
       sum(coalesce(array_length(p.amenities, 1), 0)) as after_total
from properties p
join properties_amenities_backup_20261016 b on b.id = p.id
where p.amenities is distinct from b.amenities
group by p.listing_status
order by changed desc;


